import { join } from "node:path";
import { buildTheme, legacyFromBuild } from "./build";
import { BUILT_IN_PALETTES, type PaletteSpec } from "./color/palettes";
import { emitNative } from "./emit-native";
import { emitWeb } from "./emit-web";

// Generated by this package's own build (dist/native/theme.d.ts); see OQ-15 in docs/plans/phase-0.md.
export type { UnisonTheme } from "@unison-ui/tokens/native";
export type { Token } from "./build";
export { wcagRatio, wcagRatio as contrastRatio } from "./color/contrast";
export { cssVarName } from "./emit-web";
export type { SourceToken, TokenType } from "./schema";
export type { SpringConfig } from "./spring";
export { simulateSpring, springToCssLinear } from "./spring";

/** Reads the token source in `cwd`, checks contrast and writes every output. */
export async function compile({ cwd }: { cwd: string }): Promise<string[]> {
  const palettes = BUILT_IN_PALETTES();
  const theme = buildTheme({
    name: "default",
    root: cwd,
    accent: palettes.find((p) => p.name === "accent") as PaletteSpec,
    neutral: palettes.find((p) => p.name === "gray") as PaletteSpec,
    autoContrast: true,
  });
  for (const warning of theme.warnings) console.warn(warning);
  const sets = legacyFromBuild(theme);
  return [...emitWeb(join(cwd, "dist/web"), sets), ...emitNative(join(cwd, "dist/native"), sets)];
}
